(function(root){'use strict';
const R=root.OrganismRateImport;
function columns(table){return Object.fromEntries((table[0]||[]).map((h,i)=>[R.norm(h),i]));}
function kind(table){const c=columns(table);if(c.coderisque!==undefined&&c.taux!==undefined&&c.etablissement!==undefined)return 'atmp';if(c.population!==undefined&&c.produit!==undefined&&c.tauxcotise!==undefined)return 'probtp';return 'generic';}
function atmp(table,expectedSiret){const c=columns(table),rows=[];for(const line of table.slice(1)){if(!line.some(v=>String(v??'').trim()))continue;const establishment=String(line[c.etablissement]||''),m=establishment.match(/(\d{9})[\s.-]*(\d{5})/),siret=m?m[1]+m[2]:'';if(!siret||siret!==String(expectedSiret||'').replace(/\s/g,''))throw Error('Export AT/MP : SIRET incompatible avec la fiche établissement.');rows.push({siret,atmpRate:R.rate(line[c.taux],'percent'),atmpRiskCode:String(line[c.coderisque]||'').trim(),atmpValidFrom:R.date(line[c.datedeffet]),atmpDecisionDate:R.date(line[c.datedeladecision],false,true),atmpNotificationDate:R.date(line[c.datedenotificationdeladecision],false,true),atmpRegion:String(line[c.caisseregionale]||'').trim()});}if(rows.length!==1)throw Error('Sélectionnez un export contenant un seul établissement et une seule période AT/MP.');if(!rows[0].atmpRiskCode)throw Error('Code risque absent.');return rows[0];}
function probtp(table,validFrom,validUntil=''){validFrom=R.date(validFrom,false,true);validUntil=R.date(validUntil,false,true);if(validUntil&&(!validFrom||validUntil<validFrom))throw Error('Fin de validité antérieure au début.');const c=columns(table),rows=[],pending=[];for(const [index,line]of table.slice(1).entries()){if(!line.some(v=>String(v??'').trim()))continue;const population=String(line[c.population]||'').trim(),complement=String(line[c.libellecomplementaire]||'').trim(),product=String(line[c.produit]||'').trim(),label=[product,population,complement].filter(Boolean).join(' — '),pat=String(line[c.partemployeur]||'').trim(),sal=String(line[c.partsalarie]||'').trim(),total=String(line[c.tauxcotise]||'').trim();const raw={label,population,complement,product,employeeRateRaw:sal,employerRateRaw:pat,totalRaw:total,sourceLine:index+2};
 if(/€|eur/i.test(total)){pending.push({...raw,reason:'Forfait en euros, pas un pourcentage. Répartition salarié/employeur et conditions à renseigner.'});continue;}
 if(!pat&&!sal){pending.push({...raw,reason:'Seul le taux total est fourni : répartition salarié/employeur inconnue.'});continue;}
 const employerRate=pat?R.rate(pat,'percent'):'0',employeeRate=sal?R.rate(sal,'percent'):'0';if(total&&Math.abs(Number(R.rate(total,'percent'))-Number(employerRate)-Number(employeeRate))>0.0001){pending.push({...raw,reason:'Le total ne correspond pas aux parts fournies.'});continue;}
 let category=/^ouvriers?$/i.test(population)?'Ouvrier':/^etam$/i.test(population)?'ETAM':/^cadres?$/i.test(population)?'Cadre':'Tous',baseMode='gross';
 if(/TVA/i.test(complement)){pending.push({...raw,reason:'Ligne de TVA : traitement distinct des cotisations sociales à confirmer.'});continue;}
 if(/TRANCHE A/i.test(complement))baseMode='t1';else if(/TRANCHE B/i.test(complement)){pending.push({...raw,reason:'Assiette Tranche B de prévoyance : plafond contractuel à préciser ; ne pas assimiler automatiquement à la tranche 2 Agirc-Arrco.'});continue;}
 else if(/CONGES PAYES|ICP/i.test(complement)&&!/SANS ICP/i.test(complement)){pending.push({...raw,reason:'Assiette incluant les congés payés : coefficient et règle à confirmer.'});continue;}
 rows.push({label,code:'PROBTP-'+R.norm(product+'-'+population+'-'+complement).slice(0,100),category,baseMode,base:'0',employeeRate,employerRate,validFrom,validUntil,sourceLine:index+2,excludeApprentice:/HORS APPRENTIS/i.test(complement),conditions:/CONSTRUCTYS/i.test(population)?'Effectif inférieur à 11 salariés à contrôler.':'',csgInclude:/PREVOYANCE|MEDICAUX|Prévoyance|Frais Médicaux/i.test(product)?'À vérifier':'Non'});
 }if(!rows.length&&!pending.length)throw Error('Aucune ligne PRO BTP.');return{rows,pending};}
const api={kind,atmp,probtp};root.OrganismExportAdapters=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
